<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { API } from '@/api/api'
import { $storex } from '@/store'
import { AUTONOMY_LEVELS } from './companyMeta'
