/**
 * Downscale an image file into a bounded data URL.
 *
 * The logo lives inline in the company document, so the file is resized first: a
 * multi-megabyte photo must not become a multi-megabyte company document. SVG is
 * already vector and small, so it is embedded as it is.
 *
 * @param {File} file Image picked by the owner.
 * @param {Number} maxSize Longest side of the stored image, in pixels.
 * @returns {Promise<String>} The data URL.
 */
function downscaleImage(file, maxSize = 256) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onerror = () => reject(new Error('Cannot read that file.'))
    reader.onload = () => {
      if (String(file.type) === 'image/svg+xml') {
        resolve(String(reader.result || ''))
        return
      }
      const image = new Image()
      image.onerror = () => reject(new Error('That file is not a readable image.'))
      image.onload = () => {
        try {
          const width = image.width || maxSize
          const height = image.height || maxSize
          const scale = Math.min(1, maxSize / Math.max(width, height))
          const canvas = document.createElement('canvas')
          canvas.width = Math.max(1, Math.round(width * scale))
          canvas.height = Math.max(1, Math.round(height * scale))
          const context = canvas.getContext('2d')
          context.drawImage(image, 0, 0, canvas.width, canvas.height)
          resolve(canvas.toDataURL('image/png'))
        } catch (error) {
          reject(error)
        }
      }
      image.src = String(reader.result || '')
    }
    reader.readAsDataURL(file)
  })
}

